#[test]
fn sqlite_snapshot_semio_table_controlled_native_output(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut snapshot=fixture();snapshot.rows[0].cells[4]=SemioValue::Str{value:"x".repeat(f["nativeOutputBytes"].as_u64().unwrap() as usize)};
 for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioTableSnapshot as store::ArtifactPack>::encode_pack(&snapshot)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioTableSnapshot as store::ArtifactDsl>::print_dsl(&snapshot))};assert!(actual==expected,"controlled table output differs from authored wire");
 for measured in [false,true]{let mut interior=false;let error=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=65536&&(if measured{event.total==0}else{event.total>65536&&event.completed<event.total});interior|=cancel;!cancel},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.message.contains("cancel"),"{error}");}
 for limits in [SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:4096,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_rows:0,..SqliteDatabaseLimits::default()}]{assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
}
fn fixture()->SemioTableSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();SemioTableSnapshot{schema:f["schema"].as_str().unwrap().into(),columns:f["columns"].as_array().unwrap().iter().map(|c|SemioTableColumn{name:c[0].as_str().unwrap().into(),kind:match c[1].as_str().unwrap(){"null"=>SemioTableCellKind::Null,"bool"=>SemioTableCellKind::Bool,"int"=>SemioTableCellKind::Int,"float"=>SemioTableCellKind::Float,"str"=>SemioTableCellKind::Str,_=>SemioTableCellKind::Bytes}}).collect(),rows:vec![SemioTableRow{cells:vec![SemioValue::Null,SemioValue::Bool{value:true},SemioValue::Int{lexeme:f["integerLexeme"].as_str().unwrap().into()},SemioValue::Float{lexeme:f["floatLexeme"].as_str().unwrap().into()},SemioValue::Str{value:f["text"].as_str().unwrap().into()},SemioValue::Bytes{value:vec![0,1,255]}]}]}}
fn project(value:&SemioTableSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioTableSnapshot, semio_framework_value::ValueError>{SemioTableSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_table_typed_columns_cells_lexemes_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioTableSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioTableSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioTableSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioTableSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));assert_eq!(restore(&project(&SemioTableSnapshot::default())).unwrap(),SemioTableSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_table_rejects_kind_shape_reference_alignment_and_budget_corruption(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_table_cell").unwrap().rows[0].values[1]=SqliteValue::Integer(999),1=>db.table_mut("semio_table_cell").unwrap().rows[0].values[2]=SqliteValue::Integer(999),2=>db.table_mut("semio_table_value").unwrap().rows[0].values[2]=SqliteValue::Integer(0),3=>db.table_mut("semio_table_cell").unwrap().rows[1].values[2]=SqliteValue::Integer(0),_=>{db.table_mut("semio_table_cell").unwrap().rows.remove(0);}}assert!(restore(&db).is_err());}let mut invalid=fixture();invalid.rows[0].cells.pop();assert_eq!(restore(&project(&invalid)).unwrap(),invalid);let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioTableSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_table_independent_typed_cell_join_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query('SELECT name,v.kind FROM semio_table_cell c JOIN semio_table_column t ON c.column_ordinal=t.ordinal JOIN semio_table_value v ON value_id=v.id ORDER BY t.ordinal').all();if(rows.map(r=>r.kind).join(',')!=='null,bool,int,float,str,bytes')throw Error('typed cells');db.query(\"UPDATE semio_table_value SET string_value='independently edited' WHERE kind='str'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.rows[0].cells[4]=SemioValue::Str{value:"independently edited".into()};assert_eq!(restored,expected);}

