#[test]
fn sqlite_snapshot_semio_table_erased_preserves_code_admitted_intermediate_owner(){
 use std::io::Write;use std::process::{Command,Stdio};
 let neutral:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🧩️intermediate/🔣️.json")).unwrap();let input=&neutral["snapshot"];
 use crate::standards::v1::subsets::value::schema::snapshot::{SemioValueEntry,ValueId};let cells=&input["rows"][0]["cells"];let snapshot=SemioTableSnapshot{schema:input["schema"].as_str().unwrap().into(),columns:input["columns"].as_array().unwrap().iter().map(|column|SemioTableColumn{name:column["name"].as_str().unwrap().into(),kind:SemioTableCellKind::Str}).collect(),rows:vec![SemioTableRow{cells:vec![SemioValue::Null,SemioValue::Bool{value:cells[1]["value"].as_bool().unwrap()},SemioValue::Int{lexeme:cells[2]["lexeme"].as_str().unwrap().into()},SemioValue::Float{lexeme:cells[3]["lexeme"].as_str().unwrap().into()},SemioValue::Str{value:cells[4]["value"].as_str().unwrap().into()},SemioValue::Bytes{value:cells[5]["value"].as_array().unwrap().iter().map(|value|u8::try_from(value.as_u64().unwrap()).unwrap()).collect()},SemioValue::List{items:Vec::new()},SemioValue::Map{entries:vec![SemioValueEntry{key:cells[7]["entries"][0]["key"].as_str().unwrap().into(),value:SemioValue::Null},SemioValueEntry{key:cells[7]["entries"][1]["key"].as_str().unwrap().into(),value:SemioValue::Bool{value:false}}]},SemioValue::Ref{id:ValueId{value:cells[8]["id"]["value"].as_str().unwrap().into()}}]},SemioTableRow{cells:Vec::new()}]};
 let provider=<SemioTableSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"table".into()};
 for encoding in [SnapshotEncoding::Text,SnapshotEncoding::Binary]{
  let payload=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioTableSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioTableSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};
  assert_eq!(SemioTableSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),snapshot);
  let db=(provider.export)("s.stdio.semio.table",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(restore(&db).unwrap(),snapshot);
  let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const f=JSON.parse(process.argv[1]);const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));try{if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(JSON.stringify(db.query(f.query).all())!==JSON.stringify(f.expectedRows))throw Error('full query');await Bun.write(Bun.stdout,db.serialize());}finally{db.close();}";
  let text=serde_json::to_string(&neutral).unwrap();let mut child=Command::new("bun").args(["-e",script,&text]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
  let db=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let result=(provider.import)("s.stdio.semio.table",&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
  assert_eq!(SemioTableSnapshot::decode_sqlite_snapshot_native(&result,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),snapshot);
 }
}

